insert into public.roadmap_topics (id, title, note, sort_order) values
  ('http', 'HTTP & REST fundamentals', 'Methods, status codes, headers — the language every API speaks.', 1),
  ('db', 'Databases: SQL vs NoSQL', 'When to reach for tables and joins vs documents and key-value stores.', 2),
  ('api-design', 'API design', 'Designing endpoints, request/response shapes, versioning, pagination.', 3),
  ('auth', 'Authentication & authorization', 'Sessions, tokens (JWT), OAuth — who you are vs what you can do.', 4),
  ('caching', 'Caching strategies', 'In-memory caches, CDNs, cache invalidation — the classic hard problem.', 5),
  ('queues', 'Message queues & async processing', 'Decoupling work with queues instead of doing everything synchronously.', 6),
  ('monolith-micro', 'Monolith vs microservices', 'Trade-offs in splitting an app into independently deployed services.', 7),
  ('scaling', 'Scalability & load balancing', 'Horizontal vs vertical scaling, load balancers, stateless services.', 8),
  ('system-design', 'System design basics', 'Sketching a design for something like a URL shortener or a feed.', 9),
  ('containers', 'Containers & Docker', 'Packaging an app so it runs the same everywhere.', 10),
  ('cicd', 'CI/CD pipelines', 'Automating tests and deployments so releases aren''t scary.', 11),
  ('observability', 'Observability: logs, metrics, tracing', 'Knowing what your backend is actually doing in production.', 12);
insert into public.vocab_words (en, bs, example) values
  ('deadline', 'rok', 'We need to finish this before the deadline.'),
  ('to figure out', 'shvatiti / dokučiti', 'I finally figured out why the build was failing.'),
  ('reliable', 'pouzdan', 'This library is fast and reliable.'),
  ('to rely on', 'osloniti se na', 'You can rely on her to fix it quickly.'),
  ('workaround', 'privremeno rješenje', 'There''s no real fix yet, only a workaround.'),
  ('to bring up', 'pokrenuti (temu)', 'She brought up a good point in the meeting.'),
  ('thorough', 'temeljit', 'He did a thorough review of the code.'),
  ('to catch up', 'nadoknaditi', 'I need to catch up on my emails today.'),
  ('straightforward', 'jednostavno, jasno', 'The setup was pretty straightforward.'),
  ('to look into', 'istražiti', 'Can you look into why the server is slow?'),
  ('trade-off', 'kompromis', 'Every architecture decision has trade-offs.'),
  ('to roll out', 'pustiti u rad, objaviti', 'We''re rolling out the update next week.'),
  ('in the long run', 'dugoročno gledano', 'It''s slower now but cheaper in the long run.'),
  ('to keep up with', 'pratiti (tempo/novosti)', 'It''s hard to keep up with all the new frameworks.');
insert into public.quiz_questions (quiz_key, question, options, correct_index, explain) values
  ('english', 'Which is correct?', '["I have 25 years.","I am 25 years old.","I has 25 years old.","I''m having 25 years."]'::jsonb, 1, 'In English, age uses ''to be'': I am 25 years old — not ''to have'', unlike Bosnian ''imam 25 godina''.'),
  ('english', 'Choose the correct sentence:', '["She is married with a doctor.","She is married to a doctor.","She is married on a doctor.","She married with a doctor."]'::jsonb, 1, '''Married to'' is the fixed preposition in English, even though Bosnian uses ''udana za''.'),
  ('english', 'Which is correct?', '["I''m agree with you.","I agree with you.","I''m agreeing with you.","I am agree you."]'::jsonb, 1, '''Agree'' is a normal verb, not used with ''to be'' — say ''I agree'', not ''I''m agree''.'),
  ('english', 'Pick the right option:', '["Depends of the weather.","It depends of the weather.","It depends on the weather.","It''s depend on the weather."]'::jsonb, 2, 'The fixed phrase is ''depends on'', not ''depends of''.'),
  ('english', 'Which sentence is correct?', '["I look forward to meet you.","I look forward to meeting you.","I look forward meeting you.","I''m looking forward meet you."]'::jsonb, 1, 'After ''look forward to'', use the -ing form: ''to meeting'', because here ''to'' is a preposition, not part of an infinitive.'),
  ('english', 'Choose correctly:', '["He explained me the problem.","He explained to me the problem.","He explained me about the problem.","He explained the problem to me."]'::jsonb, 3, '''Explain'' takes an object then ''to'' + person: ''explain the problem to me'' — you can''t say ''explain me''.'),
  ('english', 'Which is right?', '["I''m working here since 2019.","I work here since 2019.","I have worked here since 2019.","I was working here since 2019."]'::jsonb, 2, '''Since + a point in time'' needs the present perfect: ''I have worked here since 2019''.'),
  ('english', 'Pick the correct sentence:', '["It''s very important thing.","It''s a very important thing.","It''s very important a thing.","Is very important thing."]'::jsonb, 1, 'Singular countable nouns need an article: ''a very important thing''. Bosnian has no articles, so this one''s easy to forget.'),
  ('english', 'Which is correct?', '["I''m boring in this meeting.","I''m bored in this meeting.","I''m boring of this meeting.","I bore in this meeting."]'::jsonb, 1, '''Bored'' describes how you feel; ''boring'' describes the thing causing the feeling. The meeting is boring, you are bored.'),
  ('english', 'Choose the right option:', '["Let''s discuss about the plan.","Let''s discuss the plan.","Let''s discuss for the plan.","Let''s discussing the plan."]'::jsonb, 1, '''Discuss'' already includes the meaning of ''about'' — no preposition needed: ''discuss the plan''.'),
  ('english', 'Which is correct?', '["I need to go in the city.","I need to go to the city.","I need to go on the city.","I need go to the city."]'::jsonb, 1, 'Movement toward a place uses ''to'': ''go to the city'', not ''in the city'' (which describes location, not direction).'),
  ('english', 'Pick the correct sentence:', '["Everybody are here.","Everybody is here.","Everybody were here.","Everybody have here."]'::jsonb, 1, '''Everybody'' is grammatically singular in English, so it takes ''is'', even though it refers to many people.'),
  ('architecture', 'What does REST stand for, and what best describes it?', '["A specific programming language","An architectural style for designing networked APIs using standard HTTP methods","A database engine","A type of message queue"]'::jsonb, 1, 'REST (Representational State Transfer) is a style for structuring APIs around resources and standard HTTP verbs (GET, POST, PUT, DELETE), not a language or product.'),
  ('architecture', 'What is the main purpose of caching?', '["To permanently store all application data","To reduce load and latency by reusing previously computed or fetched results","To replace the database entirely","To encrypt data in transit"]'::jsonb, 1, 'A cache stores fast-access copies of data so repeated requests don''t have to hit a slower source (like a database) every time.'),
  ('architecture', 'In a typical relational database, what does ''normalization'' aim to reduce?', '["Query speed","Data redundancy and inconsistency","The number of tables","Network latency"]'::jsonb, 1, 'Normalization organizes data to avoid storing the same information in multiple places, reducing redundancy and the risk of inconsistent updates.'),
  ('architecture', 'What''s a key difference between a monolith and microservices?', '["Monoliths can''t use databases","Microservices split an app into independently deployable services; a monolith is one deployable unit","Microservices are always faster","Monoliths only run on one server ever"]'::jsonb, 1, 'The core distinction is deployment and boundaries: microservices are separate, independently deployable services communicating over a network; a monolith ships as a single unit.'),
  ('architecture', 'Why would you use a message queue (like RabbitMQ or SQS) between services?', '["To make services talk synchronously and instantly","To decouple services and let them process work asynchronously and reliably","To store user passwords","To replace HTTP entirely"]'::jsonb, 1, 'Queues let a producer hand off work without waiting for the consumer, smoothing out spikes and letting each side fail or scale independently.'),
  ('architecture', 'What does ''horizontal scaling'' mean?', '["Making a single server more powerful (more CPU/RAM)","Adding more machines/instances to share the load","Reducing the number of servers","Increasing database columns"]'::jsonb, 1, 'Horizontal scaling adds more instances running in parallel (often behind a load balancer), as opposed to vertical scaling, which upgrades a single machine.'),
  ('architecture', 'What is the main job of a load balancer?', '["To compress images","To distribute incoming requests across multiple servers","To store session data permanently","To write logs to disk"]'::jsonb, 1, 'A load balancer spreads traffic across several backend instances so no single server gets overwhelmed, and can reroute around failed instances.'),
  ('architecture', 'What''s the difference between authentication and authorization?', '["They are the same thing","Authentication verifies who you are; authorization decides what you''re allowed to do","Authorization verifies identity; authentication grants permissions","Neither applies to APIs"]'::jsonb, 1, 'Authentication = proving identity (e.g. login). Authorization = deciding what an authenticated identity is permitted to access or do.'),
  ('architecture', 'Why use an index on a database column?', '["To make writes faster in every case","To speed up lookups/queries on that column, at some cost to write speed","To encrypt the column","Indexes have no effect on performance"]'::jsonb, 1, 'An index lets the database find matching rows quickly without scanning the whole table, though it adds overhead to inserts/updates on that column.'),
  ('architecture', 'What is ''idempotency'' in the context of an API?', '["An API that only works once","Calling the same request multiple times has the same effect as calling it once","A type of encryption","A synonym for authentication"]'::jsonb, 1, 'An idempotent operation (like a standard PUT or DELETE) can be safely retried — repeating it doesn''t cause extra side effects, which matters a lot for reliability over unreliable networks.'),
  ('architecture', 'What''s a common reason to introduce a CDN (Content Delivery Network)?', '["To run your database","To serve static assets from servers geographically closer to users, reducing latency","To replace your backend logic","To manage user authentication"]'::jsonb, 1, 'A CDN caches and serves static content (images, JS, CSS) from edge locations near the user, cutting load times and reducing load on your origin server.'),
  ('architecture', 'In CI/CD, what does ''CI'' (Continuous Integration) mainly refer to?', '["Automatically deploying to production on every commit with no checks","Frequently merging code changes and automatically building/testing them","Manually testing code once a month","A cloud hosting provider"]'::jsonb, 1, 'CI is the practice of integrating code changes frequently and running automated builds/tests on each change, catching problems early.');
